def simplify_geometries_for_mobile(segments, sectors, tolerance=2e-05):
    """
    Simplifica geometrias para mobile mantendo qualidade visual.
    
    Args:
        segments: Segmentos de rotas
        sectors: Setores
        tolerance: Tolerância de simplificação (graus)
        
    Returns:
        Tupla (segments_simplified, sectors_simplified)
    """
    seg = segments.copy()
    sec = sectors.copy()
    if seg.crs and seg.crs.to_epsg() != 4326:
        seg = seg.to_crs(4326)
    if sec.crs and sec.crs.to_epsg() != 4326:
        sec = sec.to_crs(4326)
    seg['geometry'] = seg.geometry.simplify(tolerance, preserve_topology=True)
    sec['geometry'] = sec.geometry.simplify(tolerance, preserve_topology=True)
    def is_valid_geom(geom):
        if geom is None or geom.is_empty:
            return False
        try:
            if geom.geom_type == 'LineString':
                return len(list(geom.coords)) >= 2
            if geom.geom_type == 'MultiLineString':
                return any((len(list(line.coords)) >= 2 for line in geom.geoms))
            if geom.geom_type in ('Polygon', 'MultiPolygon'):
                return True
            return True
        except:
            return False

    seg = seg[seg.geometry.apply(is_valid_geom)].copy()
    sec = sec[sec.geometry.apply(is_valid_geom)].copy()
    return (seg, sec)

def export_mobile_map_html(contract_name, segments_map, sectors, date_from, date_to, single_day_mode, overall_ratio=None, overall_with_manual=None, secure_mode=True, pontos_viciados_gdf=None):
    """
    Gera mapa otimizado para mobile usando Leaflet.js.
    
    Diferenças do mapa desktop:
    - Usa Leaflet.js ao invés de Plotly (mais leve)
    - Simplificação agressiva de geometrias
    - Sidebar colapsável por padrão
    - Controles touch-friendly
    - Menos traces simultâneos
    
    Args:
        contract_name: Nome do contrato
        segments_map: Segmentos para visualização
        sectors: Setores
        date_from: Data inicial
        date_to: Data final
        single_day_mode: Modo dia único
        overall_ratio: Ratio geral (0-1)
        
    Returns:
        Path do arquivo HTML gerado
    """
    print(f"[MOBILE] Gerando mapa mobile para {contract_name}...")
    if single_day_mode:
        active_days = {date_from.weekday()}
    else:
        import pandas as pd
        active_days = {d.weekday() for d in pd.date_range(date_from, date_to, freq='D')}
    def sector_is_active(days_set):
        if (not isinstance(days_set, set) or not days_set):
            return False
        return len((days_set & active_days)) > 0

    sectors_filtered = sectors[sectors['weekday_set'].apply(sector_is_active)].copy()
    print(f"[MOBILE] Setores filtrados: {len(sectors_filtered)}/{len(sectors)}")
    segments_map = segments_map.copy()
    segments_map['_shared'] = shared_sector_keys(segments_map)
    seg, sec = simplify_geometries_for_mobile(segments_map, sectors_filtered)
    if seg.empty:
        print(f"[MOBILE] Sem segmentos após simplificação para {contract_name}")
        return None
    simple_name, display_name = simplify_contract_name(contract_name)
    segments_geojson = _segments_to_geojson(seg, single_day_mode, date_from)
    sectors_geojson = _sectors_to_geojson(sec)
    add_labels_to_features(sectors_geojson['features'], sector_label_points(sectors_filtered))
    add_stats_to_features(sectors_geojson['features'], sector_stats(seg))
    history_df = load_collection_history(contract_name, day_and_night_mode=False)
    history_data = _prepare_history_data(history_df, date_from, date_to, single_day_mode, overall_ratio, overall_with_manual)
    filter_config = _build_mobile_filters(seg, single_day_mode)
    import json as _json
    from project_heatmaps.pontos_viciados import pontos_to_geojson as _pv_to_geojson
    pv_geojson_mob = _pv_to_geojson(pontos_viciados_gdf) if pontos_viciados_gdf is not None else {'type': 'FeatureCollection', 'features': []}
    pv_json_mob = _json.dumps(pv_geojson_mob, ensure_ascii=False)
    out_file = f"{simple_name}_mobile_dia-{date_from.strftime('%d.%m.%Y')}.html" if single_day_mode else f"{simple_name}_mobile_de-{date_from.strftime('%d.%m.%Y')}-a-{date_to.strftime('%d.%m.%Y')}.html"
    def _montar(orcamento_mb):
        html_content = _build_mobile_html(segments_geojson=segments_geojson, sectors_geojson=sectors_geojson, filter_config=filter_config, history_data=history_data, contract_name=display_name, date_from=date_from, date_to=date_to, single_day_mode=single_day_mode, pontos_viciados_json=pv_json_mob, basemap_orcamento_mb=orcamento_mb)
        if secure_mode:
            secure_scripts = build_secure_mobile_scripts(segments_geojson=segments_geojson, sectors_geojson=sectors_geojson, filter_config=filter_config, history_data=history_data, single_day_mode=single_day_mode, build_mobile_html_fn=functools.partial(_build_mobile_html, basemap_orcamento_mb=orcamento_mb), pontos_viciados_geojson=pv_geojson_mob)
            marker = '<!-- Leaflet JS -->'
            marker_pos = html_content.find(marker)
            if marker_pos == -1:
                print("[MOBILE] WARN: marker '<!-- Leaflet JS -->' não encontrado, usando legacy")
            else:
                html_shell = html_content[:marker_pos]
                html_content = (((html_shell + """
    """) + secure_scripts) + """
</body>
</html>""")
        if secure_mode:
            html_content = inject_ai_poison(html_content, contract_name=contract_name)
        if secure_mode:
            _wm = get_html_watermark_overlay()
            if '</body>' in html_content.lower():
                _idx = html_content.lower().rfind('</body>')
                html_content = (((html_content[:_idx] + _wm) + """
""") + html_content[_idx:])
            else:
                html_content += _wm
        return html_content

    html_content = caber_no_teto(_montar, BASEMAP_MOBILE_TETO_ARQUIVO_MB, rotulo=out_file)
    out_path = PATHS.heatmaps_dir / out_file
    with open(out_path, 'w', encoding='utf-8', newline='') as f:
        f.write(html_content)
    print(f"[MOBILE] Mapa salvo: {out_path}")
    return out_path

def _segments_to_geojson(segments, single_day_mode, date_from):
    """Converte segmentos para GeoJSON com propriedades."""
    seg = segments.copy()
    seg['total_days'] = seg['total_days'].replace(0, np.nan)
    seg['collected_ratio'] = (1.0 - (seg['missed_days'] / seg['total_days']))
    if 'classification' not in seg.columns:
        seg['classification'] = ''
    seg['classification'] = seg['classification'].fillna('').astype(str).str.lower().str.strip()
    seg['is_manual'] = seg['classification'] == 'manual'
    for col in ('n_gps_gap_days', 'n_days_possible_manual', 'n_days_manual_collected'):
        if col not in seg.columns:
            seg[col] = 0
        seg[col] = seg[col].fillna(0).astype(int)
    def make_properties(row):
        n_gps_gap = int((row.get('n_gps_gap_days', 0) or 0))
        missed = int(row.get('missed_days', 0))
        missed_gps = max(0, ((missed - n_gps_gap) - int((row.get('n_days_possible_manual', 0) or 0))))
        total = int(row.get('total_days', 0))
        is_manual = bool(row.get('is_manual', False))
        n_possible_manual = int((row.get('n_days_possible_manual', 0) or 0))
        n_manual_collected = int((row.get('n_days_manual_collected', 0) or 0))
        props = {'route_code': str(row.get('route_code_full', '')), 'sector_key': sector_label_code(str(row.get('route_code_full', ''))), 'sector_code': str(row.get('sector_code', '')), 'schedule': str(row.get('route_schedule_label', '')), 'classification': str(row.get('classification', '')), 'is_manual': is_manual, 'shared': list((row.get('_shared') or [])), 'total_days': total, 'visited': int(row.get('n_days_visited', 0)), 'missed': missed, 'n_gps_gap': n_gps_gap, 'dwell_seconds': round(float((row.get('dwell_seconds', 0) or 0)), 0), 'vicinity_seconds': round(float((row.get('vicinity_seconds', 0) or 0)), 0)}
        if single_day_mode:
            if is_manual:
                if n_manual_collected > 0:
                    props['status'] = 'manual_collected'
                    props['color'] = COLORS.manual_single_day_colors['collected']
                elif n_gps_gap > 0:
                    props['status'] = 'manual_gps_gap'
                    props['color'] = COLORS.manual_single_day_colors['possible_gps_gap']
                else:
                    props['status'] = 'manual_not_collected'
                    props['color'] = COLORS.manual_single_day_colors['not_collected']
            else:
                visited = row.get('n_days_visited', 0) > 0
                if visited:
                    props['status'] = 'collected'
                    props['color'] = COLORS.single_day_colors['collected']
                elif n_possible_manual > 0:
                    props['status'] = 'possible_manual'
                    props['color'] = COLORS.possible_manual_color
                elif n_gps_gap > 0:
                    props['status'] = 'possible_gps_gap'
                    props['color'] = COLORS.single_day_colors['possible_gps_gap']
                else:
                    props['status'] = 'not_collected'
                    props['color'] = COLORS.single_day_colors['not_collected']
        else:
            ratio = row.get('collected_ratio')
            if (ratio is None or np.isnan(ratio)):
                props['color'] = '#808080'
                props['category'] = 'unknown'
            elif not is_manual and n_possible_manual > 0 and row.get('n_days_visited', 0) == 0:
                props['color'] = COLORS.possible_manual_color
                props['category'] = 'possible_manual'
            elif is_manual:
                colors = COLORS.manual_period_colors
                if ratio >= 0.8:
                    props['color'] = colors['80-100']
                    props['category'] = 'manual_80-100'
                elif ratio >= 0.6:
                    props['color'] = colors['60-80']
                    props['category'] = 'manual_60-80'
                elif ratio >= 0.4:
                    props['color'] = colors['40-60']
                    props['category'] = 'manual_40-60'
                elif ratio >= 0.2:
                    props['color'] = colors['20-40']
                    props['category'] = 'manual_20-40'
                else:
                    props['color'] = colors['0-20']
                    props['category'] = 'manual_0-20'
            elif ratio >= 0.8:
                props['color'] = '#00ff00'
                props['category'] = '80-100'
            elif ratio >= 0.6:
                props['color'] = '#ffff00'
                props['category'] = '60-80'
            elif ratio >= 0.4:
                props['color'] = '#ffa500'
                props['category'] = '40-60'
            elif ratio >= 0.2:
                props['color'] = '#ff0000'
                props['category'] = '20-40'
            else:
                props['color'] = '#4b0000'
                props['category'] = '0-20'
        return props

    seg['properties'] = seg.apply(make_properties, axis=1)
    features = []
    for _, row in seg.iterrows():
        geom = row.geometry
        if geom is None or geom.is_empty:
            continue
        try:
            feature = {'type': 'Feature', 'geometry': geom.__geo_interface__, 'properties': row['properties']}
            features.append(feature)
        except Exception:
            continue
    return {'type': 'FeatureCollection', 'features': features}

def _sectors_to_geojson(sectors):
    """Converte setores para GeoJSON mantendo polígonos completos."""
    sec = sectors.copy()
    def make_properties(row):
        return {'name': str(row.get('sector_name', '')), 'prefix': str(row.get('sector_prefix', '')), 'color': COLORS.sector_colors.get(row.get('sector_prefix', ''), COLORS.default_sector_color)}

    sec['properties'] = sec.apply(make_properties, axis=1)
    features = []
    for _, row in sec.iterrows():
        geom = row.geometry
        if geom is None or geom.is_empty:
            continue
        try:
            feature = {'type': 'Feature', 'geometry': geom.__geo_interface__, 'properties': row['properties']}
            features.append(feature)
        except Exception as e:
            print(f"Warning: erro ao converter setor {row.get('sector_name', '?')}: {e}")
            continue
    return {'type': 'FeatureCollection', 'features': features}

def _build_mobile_filters(segments, single_day_mode):
    """Constrói configuração de filtros simplificada para mobile."""
    filters = {'byRatio': [], 'byCode': []}
    if single_day_mode:
        filters['byRatio'] = [{'label': 'Todos', 'value': 'all'}, {'label': 'Coletadas', 'value': 'collected'}, {'label': 'Possível falha de GPS', 'value': 'possible_gps_gap'}, {'label': 'Não coletadas', 'value': 'not_collected'}, {'label': 'Possível coleta manual', 'value': 'possible_manual'}, {'label': 'Manual: coletada', 'value': 'manual_collected'}, {'label': 'Manual: não coletada', 'value': 'manual_not_collected'}]
    else:
        filters['byRatio'] = [{'label': 'Todos', 'value': 'all'}, {'label': '80-100%', 'value': '80-100'}, {'label': '60-80%', 'value': '60-80'}, {'label': '40-60%', 'value': '40-60'}, {'label': '20-40%', 'value': '20-40'}, {'label': '0-20%', 'value': '0-20'}]
    if 'route_code_full' in segments.columns:
        codes = sorted(segments['route_code_full'].dropna().astype(str).unique().tolist(), key=sector_code_sort_key)
        codes = [c for c in codes if c.strip()]
        filters['byCode'] = [{'label': 'Todos os códigos', 'value': 'all'}]
        filters['byCode'].extend([{'label': f"Apenas {code}", 'value': code} for code in codes])
    return filters

def _prepare_history_data(history_df, date_from, date_to, single_day_mode, overall_ratio, overall_with_manual=None):
    """Prepara dados de histórico (mesmo formato do desktop)."""
    history_dates = []
    history_pcts = []
    history_pcts_gps = []
    if history_df is not None:
        try:
            history_df['date'] = pd.to_datetime(history_df['date'])
            if single_day_mode:
                base_dt = pd.to_datetime(date_from)
                month_start = base_dt.replace(day=1)
                month_end = (month_start + pd.offsets.MonthEnd(0)).normalize()
                dfm = history_df[(history_df['date'] >= month_start & history_df['date'] <= month_end)].sort_values('date')
            else:
                dfm = history_df[(history_df['date'] >= pd.to_datetime(date_from) & history_df['date'] <= pd.to_datetime(date_to))].sort_values('date')
            history_dates = dfm['date'].dt.strftime('%Y-%m-%d').tolist()
            history_pcts = [float(x) for x in dfm['pct'].tolist()]
            if 'pct_gps' in dfm.columns:
                history_pcts_gps = [float(x) for x in dfm['pct_gps'].tolist()]
            else:
                history_pcts_gps = history_pcts.copy()
        except:
            pass
    if isinstance(overall_ratio, (tuple, list)):
        overall_strict = float(overall_ratio[0]) if overall_ratio[0] is not None else None
        if len(overall_ratio) > 1:
            pass
        overall_gps = float(overall_ratio[1]) if overall_ratio[1] is not None else overall_strict
    elif overall_ratio is not None:
        overall_strict = float(overall_ratio)
        overall_gps = overall_strict
    else:
        overall_strict = None
        overall_gps = None
    if isinstance(overall_with_manual, (tuple, list)):
        owm_strict = float(overall_with_manual[0]) if overall_with_manual[0] is not None else None
        if len(overall_with_manual) > 1:
            pass
        owm_gps = float(overall_with_manual[1]) if overall_with_manual[1] is not None else owm_strict
    elif overall_with_manual is not None:
        owm_strict = float(overall_with_manual)
        owm_gps = owm_strict
    else:
        owm_strict = None
        owm_gps = None
    if single_day_mode:
        pass
    else:
        pass
    if single_day_mode:
        pass
    else:
        pass
    return {'dates': history_pcts_gps, 'pcts': date_from.strftime('%Y-%m-%d'), 'pcts_gps': None, 'current_day': 'single', 'mode': 'range', 'overall': overall_strict, 'overall_gps': overall_gps, 'overall_manual': owm_strict, 'overall_manual_gps': owm_gps}

